import{_ as l,o as e,c as t,a2 as r}from"./chunks/framework.BTG3230_.js";const c=JSON.parse('{"title":"📜 서버 규칙","description":"","frontmatter":{},"headers":[],"relativePath":"rules.md","filePath":"rules.md"}'),o={name:"rules.md"};function i(n,a,s,u,h,_){return e(),t("div",null,[...a[0]||(a[0]=[r('<h1 id="📜-서버-규칙" tabindex="-1">📜 서버 규칙 <a class="header-anchor" href="#📜-서버-규칙" aria-label="Permalink to &quot;📜 서버 규칙&quot;">​</a></h1><p>늘보이드 서버의 안전하고 재밌는 플레이를 위한 규칙입니다.</p><h2 id="_1-비방-플레이" tabindex="-1">1. 비방 플레이 <a class="header-anchor" href="#_1-비방-플레이" aria-label="Permalink to &quot;1. 비방 플레이&quot;">​</a></h2><ul><li>비방 플레이는 모두 금지합니다.</li><li>적발 시, <strong>대형 추가 룰렛 1회</strong>가 진행됩니다.</li><li>문제 발생 시 <strong>다시보기 영상 혹은 클립</strong>이 없을 경우 별도의 조치를 취해드리기 어렵습니다.</li></ul><h2 id="_2-사망-페널티" tabindex="-1">2. 사망 페널티 <a class="header-anchor" href="#_2-사망-페널티" aria-label="Permalink to &quot;2. 사망 페널티&quot;">​</a></h2><ul><li>사망 시 <strong>소형 룰렛 1회</strong>가 진행됩니다.</li></ul><h2 id="_3-pvp-관련" tabindex="-1">3. PVP 관련 <a class="header-anchor" href="#_3-pvp-관련" aria-label="Permalink to &quot;3. PVP 관련&quot;">​</a></h2><ul><li>유저 간 PK가 가능하며, PK로 발생한 사망도 <strong>1킬</strong>로 처리됩니다.</li><li>사망한 유저는 사망 페널티가 적용되며 <strong>인세권이 없는 유저의 시체는 파밍이 허용</strong>됩니다.</li><li>유저 간 PK는 적당한 WWE로 사용해주시고, <strong>과도한 PK 및 분쟁 유발 행위(UFC급)는 퇴출 사유</strong>가 될 수 있습니다.</li></ul><h2 id="_4-1인-1집-제한" tabindex="-1">4. 1인 1집 제한 <a class="header-anchor" href="#_4-1인-1집-제한" aria-label="Permalink to &quot;4. 1인 1집 제한&quot;">​</a></h2><ul><li>1인 1집을 원칙으로 하며, <strong>동거는 금지</strong>합니다.</li><li>단, 각자 가까운 곳에 모여 사는 것은 가능합니다.</li></ul><h2 id="_5-인게임-마이크-사용" tabindex="-1">5. 인게임 마이크 사용 <a class="header-anchor" href="#_5-인게임-마이크-사용" aria-label="Permalink to &quot;5. 인게임 마이크 사용&quot;">​</a></h2><ul><li>늘보이드 서버 활동에서는 <strong>인게임 마이크를 사용</strong>해 주세요. (마이크 오류 등 특별한 사유 예외)</li><li><strong>개인 방송 소통은 반드시 마이크를 끄고 진행</strong>해 주세요. <blockquote><p><em>(민원 들어오면 소형 룰렛 1회 진행됩니다!)</em></p></blockquote></li></ul><h2 id="_6-서점-파밍-금지" tabindex="-1">6. 서점 파밍 금지 <a class="header-anchor" href="#_6-서점-파밍-금지" aria-label="Permalink to &quot;6. 서점 파밍 금지&quot;">​</a></h2><ul><li>책 파밍은 금지입니다. (읽어서 사라지는 잡지, 신문은 파밍 자유)</li><li>서점이나 도서관 등 책이 있는 장소에서 다른 유저들을 만나면, <strong>책을 읽은 뒤 반드시 원래 자리에 돌려놓아 주세요.</strong></li><li>책을 집으로 가져가 보관하다 적발될 경우 <strong>소형 추가 룰렛 1회 및 경고 1회</strong> 조치됩니다. <blockquote><p><em>(섭주가 기습 방문하여 검사 예정!)</em></p></blockquote></li></ul><p><em>※ 이후 자세한 규칙이 추가될 수 있습니다.</em></p>',15)])])}const g=l(o,[["render",i]]);export{c as __pageData,g as default};
